mapper.select:
SELECT
, s.name as creator_name ,e.name as editor_name
FROM group_area_info r left join sys_user s on r.creator_id=s.id left join sys_user e on r.editor_id=e.id
AND ${page.where}
AND r.group_id =#{groupId }
AND r.area_code =#{areaCode }
AND r.IS_VALID =1
AND CREATOR_NAME like concat(concat('%',#{creatorName,jdbcType=VARCHAR}),'%')
AND r.EDITOR_NAME like concat(concat('%',#{editorName,jdbcType=VARCHAR}),'%')
ORDER BY ${page.orderBy}
ORDER BY r.id desc
